/// <summary>
/// MPJ_5012_RebateProcess
/// Class <c>METGUPPriceDiscPricingRulePreview_InventTable_Extension</c>
/// </summary>
[ExtensionOf(formDataSourceStr(GUPPriceDiscPricingRulePreview, InventTable))]
final class METGUPPriceDiscPricingRulePreview_InventTable_Extension
{
    public GUPRefRecId pricingRuleCopyRuleId;
}

Method.Source:
/// <summary>
/// Form data source initialization method
/// </summary>
public void init()
{
    next init();
    GUPPricingRulePreviewTrans pricingRulePreviewTrans = element.args().record() as GUPPricingRulePreviewTrans;
    this.parmPricingRuleCopyRuleId(GUPPricingRuleCopy::findByRuleId(pricingRulePreviewTrans.PricingRuleLine).RuleId);
}

GUPRefRecId parmPricingRuleCopyRuleId(GUPRefRecId _pricingRuleCopyRuleId = pricingRuleCopyRuleId)
{
    pricingRuleCopyRuleId = _pricingRuleCopyRuleId;
    return pricingRuleCopyRuleId;
}

    /// <summary>
    /// Method to find the METExcludeForPaymentProducts table record based on Rule Id and Item Id
    /// </summary>
    /// <param name = "_itemId">Item Id matching record in METExcludeForPaymentProducts table</param>
    /// <returns>METExcludeForPaymentProducts table record</returns>
    public Valid isExcluded(ItemId _itemId)
    {
        METExcludeForPaymentProducts    excludeForPaymentProds;
        GUPRefRecId                     pricingRuleCopyRuleIdLoc = this.parmPricingRuleCopyRuleId();

        select firstonly RecId from excludeForPaymentProds
            where excludeForPaymentProds.RuleId == pricingRuleCopyRuleIdLoc 
               && excludeForPaymentProds.ItemId == _itemId;

        return excludeForPaymentProds.RecId;
    }

/// <summary>
/// Method to toggle the display of buttons
/// </summary>
/// <param name = "_showExclude">Boolean value that indicates whether to display the control</param>
public void toggleIncludeExcludeButtonVisibility(Valid _showExclude)
{
    FormButtonControl excludeIncludeForPaymentBtn;
    excludeIncludeForPaymentBtn = this.formRun().design().controlName(formControlStr(GUPPriceDiscPricingRulePreview, METExcludeForPaymentBtn)) as FormButtonControl;
    excludeIncludeForPaymentBtn.visible(_showExclude);
    excludeIncludeForPaymentBtn = this.formRun().design().controlName(formControlStr(GUPPriceDiscPricingRulePreview, METIncludeForPaymentBtn)) as FormButtonControl;
    excludeIncludeForPaymentBtn.visible(!_showExclude);
}

/// <summary>
/// Display method to show if Products are excluded for payment
/// </summary>
/// <param name = "_inventTable">Invent Table record of the grid</param>
/// <returns>Boolean value to indicate Yes/No</returns>
public display NoYes displayExcludeForPayment(InventTable _inventTable)
{
    return this.isExcluded(_inventTable.ItemId) ? NoYes::Yes : NoYes::No;
}

/// <summary>
/// Method to control the display of Newly added Rebate buttons
/// </summary>
public void markChanged()
{
    next markChanged();
    
    MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();
    InventTable inventTableExclusion;
    selectionHelper.parmDatasource(this);
    inventTableExclusion = selectionHelper.getFirst();
    
    while (inventTableExclusion)
    {
        if (this.isExcluded(inventTableExclusion.ItemId))
        {
            this.toggleIncludeExcludeButtonVisibility(false);
            return;
        }
        inventTableExclusion = selectionHelper.getNext();
    }
    
    this.toggleIncludeExcludeButtonVisibility(true);
}
